// Shared read side of the canonical host projection.
//
// Roles already reached every harness through src/lib/roster/index.mjs, so role
// text was never the duplication problem. Capabilities were: no binder projected
// skills/ at all, which left every non-Claude harness with three roles and zero
// domain capabilities. This module is the shared accessor renderers use so the
// capability catalog reaches a harness the same way the roster already does.
//
// Read-only. The projection is generated by scripts/generate-host-projection.mjs
// from the canonical owners; nothing here composes or decides.
import { readFileSync, existsSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..', '..');
const PROJECTION = resolve(ROOT, 'src/registry/host-projection.json');

export function loadHostProjection() {
  if (!existsSync(PROJECTION)) {
    throw new Error('host projection missing; run: node scripts/generate-host-projection.mjs');
  }
  return JSON.parse(readFileSync(PROJECTION, 'utf8'));
}

/**
 * Publicly discoverable domain capabilities, in catalog order.
 *
 * Explicit entrypoints are excluded: a slash command must not make an authority,
 * workflow entrypoint, or internal primitive appear as peer expertise in discovery.
 */
export function publicCapabilities() {
  return loadHostProjection().capabilities
    .filter((c) => c.kind === 'domain-capability' && c.discoverability === 'public');
}

/**
 * The compact discovery catalog as Markdown. Names and
 * one-line descriptions only; method stays in SKILL.md and loads after
 * selection, so a harness that carries this block does not preload doctrine.
 */
export function capabilityCatalogBlock() {
  const capabilities = publicCapabilities();
  if (!capabilities.length) return '';
  return [
    '## Legion capabilities',
    '',
    ...capabilities.map((c) => `- **${c.name}** — ${c.description}`),
  ].join('\n');
}

/** Declared fidelity for one harness, or null when undeclared. */
export function harnessFidelity(id) {
  return loadHostProjection().harnesses.find((h) => h.id === id) ?? null;
}
